import React, { useState } from "react";

const row = {
  display: "flex", alignItems: "center",
  justifyContent: "space-between", padding: "10px 0",
  borderBottom: "1px solid #2a2d3a",
};
const label = { fontSize: 13, color: "#9ca3af" };
const val   = { fontSize: 13, fontWeight: 600, color: "#e8e6df", minWidth: 36, textAlign: "right" };

export default function SettingsPanel({ onSettingsChange }) {
  const [conf,     setConf]     = useState(75);
  const [debounce, setDebounce] = useState(3);
  const [skip,     setSkip]     = useState(1);
  const [open,     setOpen]     = useState(false);

  function apply() {
    onSettingsChange?.({ confidenceThresh: conf / 100, debounceFrames: debounce, frameSkip: skip });
    setOpen(false);
  }

  const card = {
    background: "#1a1d27", borderRadius: 12,
    border: "1px solid #2a2d3a", marginBottom: 16,
    overflow: "hidden",
  };
  const header = {
    padding: "12px 16px", display: "flex",
    justifyContent: "space-between", alignItems: "center",
    cursor: "pointer", userSelect: "none",
  };

  return (
    <div style={card}>
      <div style={header} onClick={() => setOpen(o => !o)}>
        <span style={{ fontSize: 13, fontWeight: 600, color: "#9ca3af", letterSpacing: 0.5 }}>
          DETECTION SETTINGS
        </span>
        <span style={{ color: "#6b7280", fontSize: 12 }}>{open ? "▲ collapse" : "▼ expand"}</span>
      </div>

      {open && (
        <div style={{ padding: "0 16px 16px" }}>

          {/* Confidence threshold */}
          <div style={row}>
            <span style={label}>Confidence threshold</span>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <input type="range" min={50} max={99} step={1} value={conf}
                onChange={e => setConf(Number(e.target.value))}
                style={{ width: 120 }} />
              <span style={val}>{conf}%</span>
            </div>
          </div>

          {/* Debounce frames */}
          <div style={row}>
            <span style={label}>Debounce frames</span>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <input type="range" min={1} max={10} step={1} value={debounce}
                onChange={e => setDebounce(Number(e.target.value))}
                style={{ width: 120 }} />
              <span style={val}>{debounce}</span>
            </div>
          </div>

          {/* Frame skip */}
          <div style={{ ...row, borderBottom: "none" }}>
            <span style={label}>Process every Nth frame</span>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <input type="range" min={1} max={5} step={1} value={skip}
                onChange={e => setSkip(Number(e.target.value))}
                style={{ width: 120 }} />
              <span style={val}>{skip}</span>
            </div>
          </div>

          <div style={{ marginTop: 14, display: "flex", gap: 8 }}>
            <button
              onClick={apply}
              style={{
                padding: "7px 20px", background: "#3b5bdb", color: "#fff",
                border: "none", borderRadius: 8, fontSize: 13,
                fontWeight: 600, cursor: "pointer",
              }}>
              Apply
            </button>
            <p style={{ fontSize: 11, color: "#6b7280", alignSelf: "center", margin: 0 }}>
              Note: changes take effect on engine restart (update detector.py constants)
            </p>
          </div>
        </div>
      )}
    </div>
  );
}
